const cfg = $('Config').first().json;
const s = $input.first().json;
const since = new Date(Date.now() - cfg.days * 86400000).toISOString().slice(0, 10);
const fresh = (s.feed || []).filter(r => r.day >= since);
if (!fresh.length) return [];
const f = (s.funnel || [])[0] || {};
const lines = fresh.map(r => `- ${r.first_name} (${r.title}, ${r.company}), theory "${r.theory}", variant ${r.variant}: ${String(r.reply_text).slice(0, 160)}`);
const theories = (s.theories || []).filter(t => t.status === 'active')
  .map(t => `${t.name}: ${t.positive}/${t.sent} positive`).join('; ');
const text = [
  `${fresh.length} positive repl${fresh.length === 1 ? 'y' : 'ies'} since ${since}`,
  ...lines,
  `Funnel: ${f.sent} sent, ${f.replied} replied, ${f.positive} positive. Active theories: ${theories}.`,
  `${cfg.base_url}`,
].join('\n');
return [{ json: { text, count: fresh.length, notify_url: cfg.notify_url } }];
